import '../Estilos/Estilos.css'
import { useEffect, useState } from 'react';


const FormUsuarios = () => {
    const [credenciales, setCredenciales] = useState({
        Nombre: '',
        Documento: '',
        Celular:'',
        Estado: '',
        Correo:'',
        Area:'',
        Cargo: '',
        Usuario: '',
        Contraseña: ''
    });
     const [error, setError] = useState(''); 

     const handleChange = (e) => {
        setCredenciales({
            ...credenciales,
            [e.target.name]: e.target.value
        });
        setError('');
     }
     const handleSubmit = async (e) => {
        e.preventDefault();

        const backendUrl = 'http://localhost:4000/api/personal'; 
        try{
            const response = await fetch(backendUrl,{
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(credenciales),
            });
            const data = await response.json();
            console.log(data);
        } catch (err){
            console.error("Error", err);
        }

     };

     return (
        <>
        <form onSubmit={handleSubmit}>
            <br />
            <div className='TituloSecciones'>
                <div className='EstiloTitulos'>
                    <h2>Registrar Personal</h2>
                </div>
            </div>
            <div className='DivTodoForm'>
                <label class="EtiquetaInputForm">Nombres y Apellidos</label>
                <input
                    type="text"
                    name="Nombre"
                    id="Nombre"
                    placeholder="Nombre Completo"
                    value={credenciales.Nombre}
                    onChange={handleChange}
                    required
                />

                <input
                    type="text"
                    name="Documento"
                    id="Documento"
                    placeholder="Número de Documento"
                    value={credenciales.Documento}
                    onChange={handleChange}
                    required
                />

                <input 
                    type="text"
                    name="Celular"
                    id="Celular"
                    placeholder='Número de celular'
                    value={credenciales.Celular}
                    onChange={handleChange}
                    required
                />

                <select
                    name='Estado'
                    value={credenciales.Estado}
                    onChange={handleChange}
                    required
                >
                    <option value="">Seleccione Estado</option>
                    <option value="Activo">Activo</option>
                    <option value="Inactivo">Inactivo</option>
                </select>
            </div>
        </form>
        </>
     )

}

export default FormUsuarios
